
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_wc_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_wc", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.295496971689150e+00, -4.213367586324521e+00, -4.098346811144066e+00, -3.939141391100170e+00, -3.722458685607056e+00, -3.434567785937354e+00, -3.064935079987779e+00, -2.612589524166739e+00, -2.094353856270277e+00, -1.551565802088636e+00, -1.046392816946368e+00, -7.033033637099667e-01, -6.016246562153624e-01, -4.982094674463310e-01, -3.619154989054134e-01, -2.314315733221911e-01, -1.307929796184955e-01, -4.927831683255105e-02, -1.080525006370393e-02, -1.216191359647073e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


